import React from "react";
import Highcharts from "highcharts/highstock";
import HighchartsReact from "highcharts-react-official";

const StockChart = ({ data }) => {
  const options = {
    series: [{
      name: "종가",
      data: data.map(item => ({
        x: new Date(item.date).getTime(),
        y: item.close,
        news: item.news
      }))
    }],
    tooltip: {
      useHTML: true,
      formatter: function () {
        const newsList = this.point.news && this.point.news.length
          ? this.point.news.map(n => `<div><b>${n.title}</b>: ${n.summary}</div>`).join("")
          : "<div>뉴스 요약 없음</div>";
        return `
          <b>${Highcharts.dateFormat('%Y-%m-%d', this.x)}</b><br/>
          종가: ${this.y}<br/>
          ${newsList}
        `;
      }
    },
    xAxis: { type: "datetime" }
  };

  return (
    <HighchartsReact
      highcharts={Highcharts}
      constructorType={"stockChart"}
      options={options}
    />
  );
};

export default StockChart;
